    if (actionBox) {
      await page.mouse.move(actionBox.x + actionBox.width / 2, actionBox.y + actionBox.height / 2);
      await page.mouse.down();
      await page.mouse.up();
    }
  }
  await page.screenshot({ path: '/tmp/opencode/latest-mobile-check.jpg', type: 'jpeg', quality: 70 });
  await browser.close();
})();
