const { createRequire } = require('node:module');
const path = require('node:path');
const runtime = path.join(process.env.HOME, '.local/share/omgithub-playwright');
const requireLocal = createRequire(path.join(runtime, 'package.json'));
const { chromium } = requireLocal('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({
    viewport: { width: 390, height: 844 },
    isMobile: true,
    hasTouch: true,
    userAgent: 'Mozilla/5.0 (Linux; Android 14; Pixel 7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/127.0.0.0 Mobile Safari/537.36'
  });
  page.on('console', msg => console.log('BROWSER:', msg.type(), msg.text()));
  await page.goto('http://127.0.0.1:3002', { waitUntil: 'domcontentloaded', timeout: 45000 });
  await page.waitForTimeout(500);
  const start = page.locator('#start-button');
  await start.click();
  await page.waitForTimeout(1200);

  const base = page.locator('#joystick-base');
  const box = await base.boundingBox();
  if (!box) throw new Error('joystick missing');
  const cx = box.x + box.width / 2;
  const cy = box.y + box.height / 2;
  await page.mouse.move(cx, cy);
  await page.mouse.down();
  await page.mouse.move(cx + box.width * 0.38, cy + box.height * 0.2, { steps: 12 });
  await page.mouse.up();

  const before = await page.evaluate(() => ({
    objective: document.querySelector('#objective')?.textContent,
    clock: document.querySelector('#clock')?.textContent,
    hint: document.querySelector('#control-hint')?.textContent,
    pos: { x: window.__testPos?.x ?? 0, y: window.__testPos?.y ?? 0 }
  }));

  await page.mouse.move(260, 470); 
  await page.mouse.down();
  await page.mouse.move(300, 420, { steps: 12 });
  await page.mouse.up();

  const after = await page.evaluate(() => ({
    objective: document.querySelector('#objective')?.textContent,
    clock: document.querySelector('#clock')?.textContent,
    hint: document.querySelector('#control-hint')?.textContent,
    prompt: document.querySelector('#prompt')?.hidden,
    touchInteract: document.querySelector('#touch-interact')?.textContent
  }));

  await page.screenshot({ path: '/tmp/opencode/latest-mobile-check.jpg', type: 'jpeg', quality: 70, fullPage: false });
  console.log(JSON.stringify({ before, after }, null, 2));
  await browser.close();
})();
